function UIActivityMainDialog:InitToggleData()
    self._toggleData = {}
    self._selectedIndex = 1
    if not self._allActivityDojo then
        return
    end

    for i, v in ipairs(self._allActivityDojo) do
        local dojo = v

        --新年基金不显示
        --if checkNumber(v.type) ~= ActivityConstants.ActivityType.NewYearFund then
        table.insert(self._toggleData, {
            dojo = dojo,
            func = function()
                local open = ThirdDownloadManager:IsActivityOpenDownloadThirdPackage(dojo.type)
                if open then
                    UIModule.OpenDialog({ id = Constants.UITypeIds.ThirdPackageDownloadDialog })
                    return
                end
                self:RefreshNode(dojo.id)
            end,
        })
        --end

        if dojo.id == self._curActivityId then
            self._selectedIndex = i
        end
    end
end

function UIActivityMainDialog:FillSelf()
    ---@type ActivityTabToggleLeft
    local scr = CfUtils.GetLuaScr(self.ActivityTabToggleLeft, ActivityTabToggleLeft)
    if scr then
        scr:FillToggles(self._toggleData, self._selectedIndex)
        scr:MoeToItemByIndex(self._selectedIndex)
    end

    if self._curActivityId ~= 0 and checkInt(self._allActivityDojo[self._selectedIndex].id) == self._curActivityId then
        self:RefreshNode(self._curActivityId)
    else
        for _, v in ipairs(self._allActivityDojo) do
            local open =  ThirdDownloadManager:IsActivityOpenDownloadThirdPackage(v.type)
            if open then
                UIModule.OpenDialog({ id = Constants.UITypeIds.ThirdPackageDownloadDialog})
                return
            end
            self:RefreshNode(v.id)
            return
        end
    end
end

--刷新节点
function UIActivityMainDialog:RefreshNode(activityId)
    if checkNumber(activityId) == 0 then
        return
    end
    local dojo = self:GetDojoByActivityId(activityId)
    if not dojo then
        return
    end

    --先注销当前选择的
    if checkNumber(self._curActivityId) ~= 0 then
        local lastDojo = self:GetDojoByActivityId(self._curActivityId)
        if lastDojo then
            local node = self._activityNodes[tostring(lastDojo.id)]
            if node and node.go then
                node.go.transform.anchoredPosition3D = Vector3(0, 0, 0)
                self:SetCanvasEnabled(node, false)
                --KTool.SetActive(node.go, false)
            end
        end
    end
    self:ShowActivityNode(activityId)
end

function UIActivityMainDialog:ShowActivityNode(activityId)
    if not activityId then
        return
    end
    if not self._displayType then
        xRecord.record('10-002', string.format("click_activity_%d", checkInt(activityId)))
    else
        xRecord.record('6-009', string.format("click_community_%d", checkInt(activityId)))
    end

    local dojo = self:GetDojoByActivityId(activityId)
    if not CfUtils.IsActive(self.ImgBg.transform.parent) then
        CfUtils.SetActive(self.ImgBg.transform.parent, true)
    end
    if not string.isEmpty(dojo.bgImageUpload) then
        KTool.GetOrAddComponent(self.ImgBg.gameObject, typeof(CS.Engine.UI.WebRawImage))
        CfUtils.FillWebRawImage(self.ImgBg, dojo.bgImageUpload , true)
    else
        local rawImageC = KTool.GetComponent(self.ImgBg.gameObject, typeof(CS.Engine.UI.WebRawImage))
        if rawImageC then
            KTool.SafeDelete(rawImageC, true)
        end
        local bgImage = checkString(dojo.bgImage)
        if bgImage == '' then
            bgImage = checkString(dojo.entranceImage)
        end
        self:RefreshBg(bgImage, dojo.isIndexPic == 1)
    end
    -- 还原顶部导航栏
    ActivityUtils.RefreshNavigatorGoods()
    if self._activityNodes[tostring(activityId)] then
        self:RefreshActivityNode(activityId)
    else
        self:CreateActivityNode(activityId)
    end
end

function UIActivityMainDialog:RefreshActivityNode(activityId)
    self._curActivityId = activityId
    KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self._curActivityId)
    local dojo = self:GetDojoByActivityId(activityId)
    local node = self._activityNodes[tostring(activityId)]
    if node and not isNull(node.go) and node.scr then
        --KTool.SetActive(node.go, true)
        self:SetCanvasEnabled(node, true)

        node.scr:Refresh(dojo, self)
    end
end

