---创建一个活动页面
---@param activityId number 活动id
---@return table
function UIActivityMainDialog:CreateActivityNode(activityId, cb)
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            local dojo = self:GetDojoByActivityId(activityId)
            local type = checkInt(dojo.type)
            local config = ActivityConstants.Configs[type]
            if not config then
                return {}
            end

            local go = nil
            if config.prefabPath then
                local path = string.format("%s%s.prefab", config.prefabPath, tostring(dojo.prefab))
                if string.isEmpty(dojo.prefab) then
                    path = string.format('%s.prefab', config.prefabPath)
                end
                go = GameUtils.LoadBundleAsync(path, self.ActivityNodeGroup.gameObject, false)
            else
                go = GameUtils.LoadBundleAsyncById(config.prefabId, self.ActivityNodeGroup.gameObject, false, true)
            end

            local scr = CfUtils.GetLuaScr(go, config.scrPath)
            -- self:AddLoader(loader)
            local node = {
                go = go,
                scr = scr,
            }
            self._activityNodes[tostring(activityId)] = node
            self:RefreshActivityNode(activityId)

            if cb then
                cb()
            end
        end)
    end)
end

