---初始化activityDojo
function UIActivityMainDialog:InitActivityDojo(activities)
    self:GatherCollectionType(activities)
    self._allActivityDojo = {}
    for k, v in pairs(activities) do
        ---@type ActivityDojo
        local dojo = ActivityDojo.New()
        dojo:Fill(v)
        if checkNumber(dojo.type) == ActivityConstants.ActivityType.LuckingBag then
            ---福袋活动
            if checkNumber(dojo.luckBagId) > 0 and GoodsUtils.GetThingNo(dojo.luckBagId) > 0 then
                dojo.redDotHint = 0 ---有福袋数据显示小红点
            end
        end
        table.insert(self._allActivityDojo, dojo)
    end
    -- 排序
    table.sort(self._allActivityDojo, function(a, b)
        if checkNumber(a.sort) ~= checkNumber(b.sort) then
            return checkNumber(a.sort) > checkNumber(b.sort)
        else
            return checkNumber(a.id) > checkNumber(b.id)
        end
    end)
    ---@type PlayerComponent
    local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local currentTime = PlayerComponent:GetPlayerDojo():GetServerTime()
    local index = 3 
    if #self._allActivityDojo < 3  then
        index = 1 
    end
    ---@type ActivityDojo
    local dojo = ActivityDojo.New()
    dojo.id = -1 
    dojo.type = ActivityConstants.ActivityType.CustomTrain
    dojo.name  = localize("临界重构")
    local endTime = currentTime + 864000000
    dojo.endTime = endTime
    dojo.closeTime = endTime
    dojo.startTime = currentTime
    dojo.bgImage = "59:worldboss_bg_15.png"
    dojo.redDotHint = -1
    table.insert(self._allActivityDojo , index ,dojo )
    local activityId = KCookie.Get(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID)
    if activityId and activityId ~= 0 then
        self._curActivityId = self:FilterActivityId(activityId)
        KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, nil)
    end
end

---刷新自身
function UIActivityMainDialog:RefreshSelf()
    if self._curActivityId ~= 0 then
        KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self._curActivityId)
    end

    local type = math.max(checkInt(KCookie.Get(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_TYPE)), Constants.MainActivityType.NORMAL)
    local datas = {}
    if self._displayType then
        datas.displayType = self._displayType
    end
    GameUtils.Request(InterfaceDefine[type], datas, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local activityData = checkTable(jsonData.activities)
        ActivityUtils.ConventSecondToTimeStamp(activityData)
        -- 同步刷新 activityhome 
        if type == Constants.MainActivityType.NORMAL then
            ActivityMgr:UpdateSpecialRed(activityData)
            ActivityMgr:InitActivityHomeData(activityData)
        end
        -- 刷新活动可能会导致活动关闭，所以先隐藏当前显示的活动
        local node = self._activityNodes[tostring(self._curActivityId)]
        if node and not isNull(node.go) then
            --KTool.SetActive(node.go, false)
            self:SetCanvasEnabled(node, false)
        end
        self:InitActivityDojo(activityData)
        self:InitToggleData()
        self:FillSelf()
    end)
end

---红点变动通知处理
---@param activityId number  活动id
---@param state      number  红点状态
function UIActivityMainDialog:RedPointChangeEventHandler(activityId, state)
    local id = self:FilterActivityId(activityId)
    local dojo, index = self:GetDojoByActivityId(id)
    if dojo then
        if ActivityUtils.IsCollectionActivity(dojo) then
            local datas = dojo.collectionDatas
            for i, data in ipairs(datas) do
                if data.id == activityId then
                    data.redDotHint = checkNumber(state)
                    break
                end
            end
            dojo.redDotHint = self:CalculateCollectionNodeRedPoint(datas)
        else
            dojo.redDotHint = checkNumber(state)
        end
        ---@type ActivityTabToggleLeft
        local scr = CfUtils.GetLuaScr(self.ActivityTabToggleLeft, ActivityTabToggleLeft)
        if scr then
            scr:RefreshCellByIndex(index)
        end
    end

    --遍历活动红点,更新主界面按钮红点
    local redNum = 0  --服务器数据-1,0对应红点0,1
    for i, v in pairs(self._allActivityDojo) do
        if v.redDotHint >= 0 then
            redNum = 1
            break
        end
    end
    local strNode = self._displayType == 1 and Constants.RedPointConst.Activity or Constants.RedPointConst.Association
    GameUtils.SetRedPointNum(strNode, redNum)
end

---外部用来刷新自己的 从一个页签切换到另一个可以用这个方法
function UIActivityMainDialog:RefreshSelfByIndex(activityId)
    activityId = self:FilterActivityId(activityId)
