---页面刷新通知处理

function UIActivityMainDialog:RefreshEventHandler(data)
    local type = math.max(checkInt(KCookie.Get(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_TYPE)), Constants.MainActivityType.NORMAL)
    if data and type == Constants.MainActivityType.NORMAL then
        if self._curActivityId ~= 0 then
            KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self._curActivityId)
        end

        -- 刷新活动可能会导致活动关闭，所以先隐藏当前显示的活动
        local node = self._activityNodes[tostring(self._curActivityId)]
        if node and not isNull(node.go) then
            --KTool.SetActive(node.go, false)
            self:SetCanvasEnabled(node, false)
        end
        local activityData = checkTable(data.activities)
        ActivityUtils.ConventSecondToTimeStamp(activityData)
        self:InitActivityDojo(activityData)
        self:InitToggleData()
        self:FillSelf()
    else
        self:RefreshSelf()
    end

end

---更新主界面红点
function UIActivityMainDialog:UpdateActivityRedPoint()
    local state = -1
    for i, v in ipairs(self._allActivityDojo) do
        if checkInt(v.redDotHint) >= 0 then
            state = 0
            break
        end
    end

    if math.max(Constants.MainActivityType.NORMAL, checkInt(KCookie.Get(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_TYPE))) == Constants.MainActivityType.NORMAL then
        GameUtils.UpdateServerRedPointData({ unReceivedActivity = state })
    else
        GameUtils.UpdateServerRedPointData({ unReceivedRegress = state })
    end
end

