function UIActivityMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:UpdateActivityRedPoint()
        -- for _, v in ipairs(self._loaders) do
        --      v:Release()
        -- end
        for _, node in pairs(self._activityNodes) do
            if not isNull(node.go) then
                KTool.SafeDelete(node.go.gameObject, true)
            end
        end
        Events.RemoveListener(Constants.EventNames.ActivityRedPointChange, self._eventActivityRedPointChange)
        Events.RemoveListener(Constants.EventNames.ActivityDialogRefresh, self._eventActivityDialogRefresh)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UIActivityMainDialog:SetCanvasEnabled(node, enabled)
    if isNull(checkTable(node).go) then
        return
    end

    local canvas = KTool.GetOrAddComponent(node.go, typeof(CS.UnityEngine.Canvas))
    canvas.enabled = enabled

    if node.scr and node.scr.SetEnabled then
        node.scr:SetEnabled(enabled)
    end
end

--- 把需要集合起来的活动，集合起来
---@param activityData any
function UIActivityMainDialog:GatherCollectionType(activityData)
    -- 把需要集合的活动挑出来
    local indexList = {}
    local gatherData = {}
    local data = checkTable(activityData)
    for k, activityDt in ipairs(data) do
        local type = checkNumber(activityDt.type)
        if isNotNull(CollectionType[type]) then
            gatherData[type] = gatherData[type] or {}
            table.insert(gatherData[type], activityDt)
            table.insert(indexList, k)
        end
    end

    -- 把需要集合的活动从原数组里面删除
    for i, v in fipairs(indexList) do
        table.remove(activityData, v)
    end

    -- 构造新的集合活动，加入到原数组里面
    for type, datas in pairs(gatherData) do
        -- 集合活动的起止时间，排序和红点，根据集合内的活动来计算
        local startTime = math.maxinteger
        local endTime = math.mininteger
        local closeTime = math.mininteger
        local sort = math.mininteger
        local redDotHint = -1
        for i, data in ipairs(datas) do
            startTime = math.min(startTime, data.startTime)
            endTime = math.max(endTime, data.endTime)
            closeTime = math.max(closeTime, data.closeTime)
            sort = math.max(sort, data.sort)
            redDotHint = math.max(redDotHint, data.redDotHint)
        end

        local acd = {
            id = type,
            type = type,
            startTime = startTime,
            endTime = endTime,
            closeTime = closeTime,
            sort = sort,
            redDotHint = redDotHint,
            name = CollectionType[type](),
            prefab = datas[1].prefab, -- 这里默认集合里所有的活动的prefab都是相同的，直接拿第一个
            bgImage = datas[1].bgImage,
            isCollection = 1,
            collectionDatas = datas,
        }
        table.insert(activityData, acd)
    end
    return activityData
end

--- 计算集合节点的红点
---@param datas any
function UIActivityMainDialog:CalculateCollectionNodeRedPoint(datas)
    local redDotHint = -1
    for i, data in ipairs(datas) do
        redDotHint = math.max(redDotHint, data.redDotHint)
    end
    return redDotHint
end

---FilterActivityId
---过滤下activityId的值
---@param activityId number
function UIActivityMainDialog:FilterActivityId(activityId)
    activityId = checkNumber(activityId)
    local targetActivityId = 0
    for _, v in pairs(self._allActivityDojo) do
        if checkNumber(v.id) == activityId then
            targetActivityId = checkNumber(activityId)
            break
        else
            if isSet(v, "isCollection") then
                for _, childDojo in ipairs(v.collectionDatas) do
                    if checkNumber(childDojo.id) == activityId then
                        targetActivityId = checkNumber(v.id)
                        ActivityUtils.SetSubActivityId(activityId) -- 记录被转换前的活动id为子活动id，如果是集合活动的话会用到这个子id
                        break
                    end
                end
            end
        end
    end

    return targetActivityId
end

return UIActivityMainDialog
